// Storage utility for localStorage operations

// Seed demo accounts on first load
export const seedDemoAccounts = () => {
  const users = JSON.parse(localStorage.getItem('unihelp_users')) || [];
  const demoUsers = [
    { name: 'Alex Johnson', email: 'demo@student.edu', password: 'password123', role: 'student' },
    { name: 'Admin User', email: 'admin@unihelp.edu', password: 'admin123', role: 'admin' },
  ];
  let changed = false;
  demoUsers.forEach(demo => {
    if (!users.find(u => u.email === demo.email)) {
      users.push(demo);
      changed = true;
    }
  });
  if (changed) localStorage.setItem('unihelp_users', JSON.stringify(users));
};

export const getUsers = () => {
  try {
    return JSON.parse(localStorage.getItem('unihelp_users')) || [];
  } catch {
    return [];
  }
};

export const saveUser = (user) => {
  const users = getUsers();
  const exists = users.find(u => u.email === user.email);
  if (exists) return false;
  users.push(user);
  localStorage.setItem('unihelp_users', JSON.stringify(users));
  return true;
};

export const findUser = (email, password) => {
  const users = getUsers();
  return users.find(u => u.email === email && u.password === password) || null;
};

export const getSession = () => {
  try {
    return JSON.parse(localStorage.getItem('unihelp_session'));
  } catch {
    return null;
  }
};

export const setSession = (user) => {
  localStorage.setItem('unihelp_session', JSON.stringify(user));
};

export const clearSession = () => {
  localStorage.removeItem('unihelp_session');
};

export const getRequests = () => {
  try {
    const stored = JSON.parse(localStorage.getItem('unihelp_requests'));
    if (stored && stored.length > 0) return stored;
  } catch {}
  // Return mock data if none exist
  return [
    {
      id: 'REQ-001',
      studentId: 'demo@student.edu',
      studentName: 'Alex Johnson',
      category: 'IT',
      title: 'Wi-Fi not working in Room 204',
      description: 'Internet connection has been down for 2 days in my dorm room.',
      status: 'Resolved',
      createdAt: '2024-11-01T10:00:00Z'
    },
    {
      id: 'REQ-002',
      studentId: 'demo@student.edu',
      studentName: 'Alex Johnson',
      category: 'Hostel',
      title: 'Broken window latch',
      description: 'The window latch in Room 204 is broken and cannot be secured.',
      status: 'In Progress',
      createdAt: '2024-11-05T14:30:00Z'
    },
    {
      id: 'REQ-003',
      studentId: 'demo@student.edu',
      studentName: 'Alex Johnson',
      category: 'Academic',
      title: 'Grade discrepancy in CS301',
      description: 'My midterm grade appears incorrect. I scored 87 but 72 is recorded.',
      status: 'Pending',
      createdAt: '2024-11-10T09:15:00Z'
    },
    {
      id: 'REQ-004',
      studentId: 'other@student.edu',
      studentName: 'Maria Chen',
      category: 'Administration',
      title: 'ID card replacement',
      description: 'My student ID card was lost and I need a replacement.',
      status: 'Pending',
      createdAt: '2024-11-11T11:00:00Z'
    },
    {
      id: 'REQ-005',
      studentId: 'other@student.edu',
      studentName: 'Maria Chen',
      category: 'IT',
      title: 'Portal login issue',
      description: 'Cannot access the student portal since the password reset.',
      status: 'In Progress',
      createdAt: '2024-11-12T08:45:00Z'
    }
  ];
};

export const saveRequests = (requests) => {
  localStorage.setItem('unihelp_requests', JSON.stringify(requests));
};

export const addRequest = (request) => {
  const requests = getRequests();
  requests.unshift(request);
  saveRequests(requests);
};

export const updateRequestStatus = (id, status) => {
  const requests = getRequests();
  const updated = requests.map(r => r.id === id ? { ...r, status } : r);
  saveRequests(updated);
  return updated;
};

export const generateId = () => {
  const requests = getRequests();
  const num = requests.length + 1;
  return `REQ-${String(num).padStart(3, '0')}`;
};
